WITH "set_with_sku" AS (SELECT DISTINCT "t0"."order_id" AS "key" FROM "sales"."order_items" AS "t0" WHERE ("t0"."sku" = 'SKU-1') AND ("t0"."order_id" IS NOT NULL)) SELECT "t1"."region" AS "region", SUM(CASE WHEN "t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00' THEN "t0"."net_amount" END) AS "net_revenue" FROM "sales"."orders" AS "t0" LEFT JOIN "sales"."branches" AS "t1" ON "t0"."branch_id" = "t1"."branch_id" WHERE ("t0"."status" = 'DONE') AND ("t0"."order_id" IN (SELECT "key" FROM "set_with_sku")) AND ("t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00') GROUP BY "t1"."region" ORDER BY "net_revenue" DESC LIMIT 1000
